use serde_json::{Value, json};
use t3_client::thread_views::{
    composer::{
        editor::{BuildOptions, build_document},
        markdown_source::{EditorSelection, normalize_selection},
    },
    document::Selection,
};
fn canonical(node: &mut Value) {
    if let Some(fields) = node.as_object_mut() {
        // These fixtures were captured without the list items' source attrs (indent, marker,
        // space); the editor goldens pin those. This file pins text nodes and selections.
        if fields.get("type").and_then(Value::as_str) == Some("listItem") {
            fields.remove("attrs");
        }
        for field in ["attrs", "marks", "content"] {
            if fields.get(field).is_some_and(|v| {
                v.as_object().is_some_and(|x| x.is_empty())
                    || v.as_array().is_some_and(|x| x.is_empty())
            }) {
                fields.remove(field);
            }
        }
        if let Some(attrs) = fields.get_mut("attrs").and_then(Value::as_object_mut) {
            attrs.remove("type");
        }
        for value in fields.values_mut() {
            canonical(value);
        }
    } else if let Some(values) = node.as_array_mut() {
        let mut merged: Vec<Value> = Vec::new();
        for node in values.iter() {
            if node["type"] == "text"
                && merged.last().is_some_and(|old| {
                    old["type"] == "text" && old.get("marks") == node.get("marks")
                })
            {
                if let Some(old) = merged.last_mut() {
                    old["text"] = json!(format!(
                        "{}{}",
                        old["text"].as_str().expect("text"),
                        node["text"].as_str().expect("text")
                    ));
                }
            } else {
                merged.push(node.clone());
            }
        }
        *values = merged;
        for value in values {
            canonical(value);
        }
    }
}
#[test]
fn source_rewrites_preserve_text_node_and_all_selection_kinds() {
    let cases: Vec<Value> = serde_json::from_str(CASES).expect("fixtures");
    for (index, case) in cases.into_iter().enumerate() {
        let doc = build_document(
            case["text"].as_str().expect("text"),
            BuildOptions::default(),
            |_| None,
            |_, _| false,
        );
        let from = case["input"]["from"].as_u64().expect("from") as usize;
        let selection = match case["input"]["kind"].as_str().expect("kind") {
            "all" => EditorSelection::All,
            "node" => EditorSelection::Node(from),
            _ => EditorSelection::Text(Selection::caret(from)),
        };
        let next = normalize_selection(
            &doc,
            selection,
            case["typed"] == true,
            case["takesBefore"] == true,
        );
        let range = next.selection.range(&next.document);
        let kind = match next.selection {
            EditorSelection::All => "all",
            EditorSelection::Node(_) => "node",
            _ => "text",
        };
        let mut actual = next.document;
        let mut expected = case["tree"].clone();
        canonical(&mut actual);
        canonical(&mut expected);
        assert_eq!(actual, expected, "tree {index} {}", case["text"]);
        assert_eq!(
            json!({"kind":kind,"from":range.from(),"to":range.to(),"anchor":range.anchor,"head":range.head}),
            case["selection"],
            "selection {index} {}",
            case["text"]
        );
    }
}
